from google.cloud import speech_v1p1beta1 as speech

def create_speech_client():
    return speech.SpeechClient()

def batch_transcribe(client, audio_uri, output_uri, language_code='en-US'):
    config = speech.RecognitionConfig(
        encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
        sample_rate_hertz=16000,
        language_code=language_code,
    )
    audio = speech.RecognitionAudio(uri=audio_uri)
    response = client.batch_transcribe(
        recognition_config=config,
        input_uri=audio_uri,
        output_uri=output_uri,
    )
    return response

def normalize_response(response):
    if response.results:
        return [result.alternatives[0].transcript for result in response.results]
    else:
        return []

from google.cloud import speech_v1
from google.cloud.speech_v1 import enums
from google.auth import default

def create_speech_client():
    credentials, project = default()
    client = speech_v1.SpeechClient(credentials=credentials)
    return client

def create_batch_config(config_name, audio_file_path):
    config = {
        'encoding': enums.RecognitionConfig.AudioEncoding.LINEAR16,
        'sample_rate_hertz': 16000,
        'language_code': 'en-US',
    }
    audio = {
        'uri': audio_file_path,
    }
    return {
        'config': config,
        'audio': audio,
        'output_config': {
            'gcs_uri': f'gs://{config_name}/output'
        }
    }

import boto3

def poll_transcription_job(job_name):
    transcribe = boto3.client('transcribe')
    while True:
        response = transcribe.get_transcription_job(TranscriptionJobName=job_name)
        job_status = response['TranscriptionJob']['TranscriptionJobStatus']
        if job_status in ['COMPLETED', 'FAILED']:
            break
    if job_status == 'COMPLETED':
        transcript_url = response['TranscriptionJob']['Transcript']['TranscriptFileUri']
        return transcript_url
    else:
        return 'Transcription job failed'

if __name__ == '__main__':
    job_name = 'example_job_name'
    transcript_url = poll_transcription_job(job_name)
    print(transcript_url)
